    36→	/**
    37→	 * Key is the line, value is a set of test methods that execute that line
    38→	 */
    39→	protected Map<Location, Set<TestMethod>> resultExecution = new HashMap<>();
    40→
    41→	/**
    42→	 * Map between executed test methods and their result. True if passing, false is failing.
    43→	 */
    44→	protected Map<TestMethod, Boolean> tests = new HashMap<>();
    45→
    46→	/**
    47→	 * Processes a wrapper for the coverage from a single test unit
    48→	 *
    49→	 * @param iCovWrapper The coverage information related to the single unit test
    50→	 * @param testClasses Classes which contain tests
    51→	 */
    52→	public void processSingleTest(CoverageFromSingleTestUnit iCovWrapper, Set<String> testClasses) {
    53→		CoverageDetailed covLine = iCovWrapper.getCov();
    54→
    55→		if (iCovWrapper.isSkip()) {
    56→			logger.debug("Ignoring skipped test: " + iCovWrapper.getTestMethod().getFullyQualifiedMethodName());
    57→			return;
    58→		}
    59→
    60→		boolean isPassing = iCovWrapper.isPassing();
    61→
    62→		// Let's navigate the covered class per line.
    63→		for (String iClassNameCovered : covLine.getDetailedCoverage().keySet()) {
    64→
    65→			String className = iClassNameCovered.replace("/", ".");
    66→			if (!config.isCoverTests() && testClasses.contains(className)) {
    67→				continue;
    68→			}
    69→
    70→			// Lines covered in that class
    71→			CoverageFromClass lines = covLine.getDetailedCoverage().get(iClassNameCovered);
    72→
    73→			for (int iLineNumber : lines.getCov().keySet()) {
    74→
    75→				int instExecutedAtLineI = lines.getCov().get(iLineNumber);
    76→
    77→				this.add(new Location(className, iLineNumber), iCovWrapper.getTestMethod(), instExecutedAtLineI, isPassing);
    78→
    79→			}
    80→		}
    81→
    82→		// Now, we check if any exception was thrown and, if so, add the line where it was thrown
    83→		// since JaCoCo does not include them in coverage
    84→		// Handle tests that throw exceptions
    85→		CoveredTestResultPerTestMethod result = iCovWrapper.getCoveredTestResultPerTestMethod();
    86→		TestMethod testMethod = iCovWrapper.getTestMethod();
    87→		if (!isPassing && result.getFailureOf(testMethod.getFullyQualifiedMethodName()) != null) {
    88→
    89→			try {
    90→				StackTrace trace = StackTraceParser
    91→						.parse(result.getFailureOf(testMethod.getFullyQualifiedMethodName()).stackTrace);
    92→
    93→				for (StackTraceElement element : trace.getStackTraceLines()) {
    94→					// Search for first non-native element
    95→					if (!element.isNativeMethod()) {
    96→						// We want to keep it if and only if it the class was included in the coverage
    97→						// computation, which will ignore classes like org.junit.Assert
    98→						if (classToInclude(element.getClassName())) {
    99→
   100→							// We also want to ignore test classes if they coverTests is not set
   101→							if (!config.isCoverTests() && testClasses.contains(element.getClassName())) {
   102→								continue;
   103→							}
   104→
   105→							Location location = new Location(
   106→									element.getClassName(),
   107→									element.getLineNumber()
   108→							);
   109→
   110→							logger.debug("Adding a line where an exception was thrown: " + location);
   111→							this.add(location, testMethod, 1, false);
   112→
   113→							// Compute the executed lines from the block where the exception was thrown
   114→							// See: https://github.com/SpoonLabs/flacoco/issues/109
   115→							SpoonBlockInspector blockMatcher = new SpoonBlockInspector(config);
   116→							List<Location> locations = blockMatcher.getBlockLocations(element);
   117→
   118→							for (Location blockLocation : locations) {
   119→								logger.debug("Adding a line from the block where an exception was thrown: " + blockLocation);
   120→								this.add(blockLocation, testMethod, 1, false);
   121→							}
   122→						}
   123→					}
   124→				}
   125→			} catch (Exception e) {
   126→				throw new RuntimeException(e);
   127→			}
   128→		}
   129→	}
   130→
   131→	public Map<Location, Set<TestMethod>> getResultExecution() {
   132→		return resultExecution;
   133→	}
   134→
   135→	public Map<TestMethod, Boolean> getTests() {
   136→		return tests;
   137→	}
   138→
   139→	public Set<TestMethod> getFailingTestCases() {
   140→		return this.tests.entrySet().stream().filter(x -> !x.getValue())
   141→				.map(Map.Entry::getKey).collect(Collectors.toSet());
   142→	}
   143→
   144→	/**
   145→	 * Auxiliary method to introduce the gathered information about a test unit run in the coverage matrix
   146→	 * <p>
   147→	 * The modifier is public for testing purposes
   148→	 *
   149→	 * @param location The location to be added
   150→	 * @param testMethod The test method which covered the location
   151→	 * @param instExecutedAtLineI Number of instructions executed at the location
   152→	 * @param testResult The result of the test method
   153→	 */
   154→	public void add(Location location, TestMethod testMethod, int instExecutedAtLineI, Boolean testResult) {
   155→		if (instExecutedAtLineI > 0) {
   156→			Set<TestMethod> currentExecution;
   157→
   158→			if (this.resultExecution.containsKey(location)) {
   159→				currentExecution = this.resultExecution.get(location);
   160→			} else {
   161→				currentExecution = new HashSet<>();
   162→				this.resultExecution.put(location, currentExecution);
   163→			}
   164→
   165→			currentExecution.add(testMethod);
   166→		}
   167→
   168→		this.tests.put(testMethod, testResult);
   169→	}
   170→
   171→	/**
   172→	 * Computes if a given class is to be included in the post-coverage computation
   173→	 *
   174→	 * If we have include-exclude patterns for Jacoco:
   175→	 * - We include the class if it matches the include patterns and does not match the excludes patterns
   176→	 * Else:
   177→	 * - We include the class if it is available in the binary directories
   178→	 * @param className
   179→	 * @return true if the class should be included in the coverage result, false otherwise
   180→	 */
   181→    private boolean classToInclude(String className) {
   182→        // False if it matches an excludes pattern
   183→        for (String pattern : config.getJacocoExcludes()) {
   184→            WildcardMatcher matcher = new WildcardMatcher(pattern);
   185→            if (matcher.matches(className)) {
   186→                return false;
   187→            }
   188→        }
   189→        // True if it matches an includes pattern and doesn't match any excludes pattern
   190→        for (String pattern : config.getJacocoIncludes()) {
   191→            WildcardMatcher matcher = new WildcardMatcher(pattern);
   192→            if (matcher.matches(className)) {
   193→                return true;
   194→            }
   195→        }
   196→
   197→        // True if it is present in the available binaries
   198→        for (String dir : config.getBinJavaDir()) {
   199→            DirectoryScanner directoryScanner = new DirectoryScanner(new File(dir), TestListResolver.getWildcard());
   200→            if (directoryScanner.scan().getClasses().contains(className)) {
   201→                return true;
   202→            }
   203→        }
   204→        for (String dir : config.getBinTestDir()) {
   205→            DirectoryScanner directoryScanner = new DirectoryScanner(new File(dir), TestListResolver.getWildcard());
   206→            if (directoryScanner.scan().getClasses().contains(className)) {
   207→                return true;
   208→            }
   209→        }
   210→
   211→        return false;
   212→    }
   213→
   214→}
